char *pure_strtok2(char **cursor, const char delim)
{
    char *str;
    char *end;

    if (cursor == NULL || (str = *cursor) == NULL) {
        return NULL;
    }
    end = str;
    while (*end != 0 && *end != delim) {
        end++;
    }
    if (*end == delim) {
        *end = 0;
        *cursor = end + 1;
    } else {
        *cursor = NULL;
    }

    return str;
}

