static int checknamesanity(const char *name, int dot_ok)
{
    const char *namepnt;

    if (name == NULL || *name == 0) {
        return -1;
    }
    /* optimize . and .. */
    if (name[0] == '.' && (name[1] == 0 || (name[1] == '.' && name[2] == 0))) {
        return 0;
    }
    namepnt = name;
    while (*namepnt != 0) {
        if (ISCTRLCODE(*namepnt) || *namepnt == '\\') {
            return -1;
        }
        if (dot_ok == 0) {
            if (*namepnt == '/') {
                namepnt++;
            } else if (namepnt != name) {
                namepnt++;
                continue;
            }
            if (namepnt[0] == 0) {
                return 0;
            }
            if (namepnt[0] == '.') {
                if (namepnt[1] == 0) {
                    return 0;
                }
                if (namepnt[1] == '.') {
                    if (namepnt[2] == 0) {
                        return 0;
                    }
                    if (namepnt[2] != '/') {
                        return -1;
                    }
                } else if (namepnt[1] != '/') {
                    return -1;
                }
            }
            if (namepnt != name) {
                continue;
            }
        }
        namepnt++;
    }
    return 0;
}

